#include "navcore/navcore.hpp"
#include <cmath>
#include <functional>
#include <iostream>
#include <stdexcept>
static void ok(bool b,const char*m){if(!b)throw std::runtime_error(m);} static void bad(const std::function<void()>&f){try{f();}catch(const std::exception&){return;}throw std::runtime_error("expected error");} static bool edge(const navcore::RoadGraph&g,const std::string&a,const std::string&b){for(const auto&e:g.outgoing(a))if(e.to==b)return true;return false;} static const navcore::Edge& find(const navcore::RoadGraph&g,const std::string&id){for(const auto&n:g.nodes())for(const auto&e:g.outgoing(n.first))if(e.osm_way_id==id)return e;throw std::runtime_error("edge missing");}
int main(){try{auto g=navcore::load_osm_map("data/sample_map.osm");ok(g.node_count()==5,"OSM node parsing");ok(edge(g,"2","3")&&!edge(g,"3","2"),"oneway yes direction");ok(edge(g,"4","3")&&!edge(g,"3","4"),"oneway minus one direction");for(const auto&n:g.nodes())for(const auto&e:g.outgoing(n.first))ok(e.osm_way_id!="104"&&e.osm_way_id!="105","access motor vehicle filtering");auto e=find(g,"100");ok(std::fabs(e.speed_limit_kph-60)<1e-9,"numeric maxspeed");ok(std::fabs(e.length_m-navcore::haversine_m(g.node(e.from),g.node(e.to)))<.01,"Haversine length");ok(std::fabs(e.travel_time_s-e.length_m/(60.0/3.6))<.01,"travel time");ok(navcore::default_speed_kph("residential")==30&&navcore::default_speed_kph("service")==15,"default profiles");auto one=navcore::match_point(g,{31.2300,121.4750,90});ok(one.osm_way_id=="100","heading tie break");auto junction=navcore::match_point(g,{31.2300,121.4800,90});ok(junction.osm_way_id=="100","intersection candidate ranking");auto seq=navcore::match_sequence(g,navcore::load_gps_trace("data/sample_trace.csv"));ok(seq.size()==3&&seq[0].candidate_count>0,"sequence candidates");bad([&]{navcore::match_point(g,{0,0,{}});});auto r=navcore::route_from_matches(g,seq);ok(!r.path_nodes.empty()&&!r.path_edges.empty(),"GPS route integration");ok(r.path_nodes.front()==seq.front().matched_edge.from&&r.path_nodes.back()==seq.back().matched_edge.to,"route matched endpoints");std::cout<<"v2 tests passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}